package bowling

import "errors"

var (
	errNegativeRoll      = errors.New("Negative roll is invalid")
	errPinCountExceeds   = errors.New("Pin count exceeds pins on the lane")
	errRollAfterGameOver = errors.New("Cannot roll after game is over")
	errGameIncomplete    = errors.New("Score cannot be taken until the end of the game")
)

// Game keeps track of the state and score of a bowling game.
type Game struct {
	rolls       []int
	frame       int     // current frame index, 0-9; 10 means the game is over
	pinsInFrame int     // pins knocked down in the current frame (or sub-frame in the 10th)
	tenthRolls  int     // number of rolls made in the 10th frame
	tenthFirst  int     // pins knocked down on the first roll of the 10th frame
	tenthSecond int     // pins knocked down on the second roll of the 10th frame
}

// NewGame returns a new bowling game.
func NewGame() *Game {
	return &Game{}
}

// Roll records a throw of `pins` pins. It returns an error if the roll is
// invalid or the game is already over.
func (g *Game) Roll(pins int) error {
	if pins < 0 {
		return errNegativeRoll
	}
	if pins > 10 {
		return errPinCountExceeds
	}
	if g.frame >= 10 {
		return errRollAfterGameOver
	}

	if g.frame < 9 {
		// Frames 1-9: a frame holds at most 10 pins across its rolls.
		if g.pinsInFrame+pins > 10 {
			return errPinCountExceeds
		}
		g.pinsInFrame += pins
		if g.pinsInFrame == 10 {
			g.frame++
			g.pinsInFrame = 0
		}
	} else {
		// The 10th frame allows up to three rolls.
		if g.pinsInFrame+pins > 10 {
			return errPinCountExceeds
		}
		g.pinsInFrame += pins
		if g.pinsInFrame == 10 {
			g.pinsInFrame = 0
		}
		switch g.tenthRolls {
		case 0:
			g.tenthFirst = pins
		case 1:
			g.tenthSecond = pins
		}
		g.tenthRolls++
		if g.tenthComplete() {
			g.frame++
		}
	}

	g.rolls = append(g.rolls, pins)
	return nil
}

// tenthComplete reports whether the 10th frame is finished.
func (g *Game) tenthComplete() bool {
	switch g.tenthRolls {
	case 0, 1:
		return false
	case 2:
		// A third roll is only allowed after a strike or a spare.
		return !(g.tenthFirst == 10 || g.tenthFirst+g.tenthSecond == 10)
	default:
		return true
	}
}

// Score returns the total score of a completed game, or an error if the game
// is not yet finished.
func (g *Game) Score() (int, error) {
	if g.frame < 10 {
		return 0, errGameIncomplete
	}

	rolls := g.rolls
	total := 0
	i := 0
	for frame := 0; frame < 10; frame++ {
		switch {
		case rolls[i] == 10:
			// Strike: 10 plus the next two rolls as bonus.
			total += 10 + rolls[i+1] + rolls[i+2]
			i++
		case rolls[i]+rolls[i+1] == 10:
			// Spare: 10 plus the next roll as bonus.
			total += 10 + rolls[i+2]
			i += 2
		default:
			// Open frame.
			total += rolls[i] + rolls[i+1]
			i += 2
		}
	}
	return total, nil
}

